// CONTROL LIBRARY - standard processes with process-map steps, risks, controls and SoD rules.
// A starting point that a company tailors (owners, frequencies, systems); not a substitute
// for scoping based on the company's own significant accounts and risks.

export type Freq = "Annual" | "Quarterly" | "Monthly" | "Weekly" | "Daily" | "Multiple times a day" | "As needed";
export type Nature = "Manual" | "Automated" | "IT-dependent manual";
export interface Risk { id: string; text: string; assertions: string[]; level: "High" | "Medium" | "Low" }
export interface Control {
  id: string; process: string; risk: string; text: string; key: boolean; type: "Preventive" | "Detective"; nature: Nature; freq: Freq;
  owner: string; performer: string; reviewer: string; evidence: string; test: string; coso: number; regs: string[]; custom?: boolean;
}
export interface Step { id: string; lane: string; label: string; controls: string[] }
export interface Process { id: string; name: string; objective: string; lanes: string[]; steps: Step[]; risks: Risk[]; controls: Control[]; sod: [string, string, string][] }

// Assertions: E/O existence/occurrence, C completeness, A accuracy, V valuation, CO cut-off, R&O rights & obligations, P&D presentation & disclosure.
const FIN = ["sox404", "in-ifc-audit", "in-ifc-board"];
type CArgs = [string, string, string, boolean, "P" | "D", "M" | "A" | "I", Freq, string, string, string, string, string, number, string[]?];
function build(pid: string, rows: CArgs[], fin = true): Control[] {
  return rows.map(([id, risk, text, key, t, n, freq, owner, performer, reviewer, evidence, test, coso, extra]) => ({ id, process: pid, risk, text, key, type: t === "P" ? "Preventive" : "Detective",
    nature: n === "A" ? "Automated" : n === "I" ? "IT-dependent manual" : "Manual", freq, owner, performer, reviewer, evidence, test, coso, regs: [...(fin ? FIN : []), ...(extra || [])] }));
}
const R = (id: string, text: string, assertions: string, level: Risk["level"] = "High"): Risk => ({ id, text, assertions: assertions.split(","), level });
const S = (id: string, lane: string, label: string, controls: string = ""): Step => ({ id, lane, label, controls: controls ? controls.split(",") : [] });

